rows.forEach(function(r){
var loaded=r.data_status==='data_loaded',
 paused=r.is_paused===true,
 busy=state.busy[r.source_key]===true,
 checked=state.selected[r.source_key]===true,
 review=r.review_note||'',
 reviewHtml=review?'<div style="display:flex;align-items:flex-start;gap:9px;color:#5b6472;font-size:14px;line-height:1.35;">'+icon(/no central mapping|review required/i.test(review)?'error':'warning',20)+'<span>'+escapeHtml(review)+'</span></div>':'<div style="display:flex;align-items:center;gap:9px;color:#5b6472;font-size:14px;">'+icon('check',20)+'<span>Mapped</span></div>';

html+='<tr style="border-bottom:1px solid #edf0f3;height:92px;transition:background .15s;">'+
'<td style="padding:0 10px;text-align:center;"><input type="checkbox" data-select="'+escapeHtml(r.source_key)+'" '+(checked?'checked':'')+' '+(!loaded||busy?'disabled':'')+' style="width:18px;height:18px;cursor:'+(loaded&&!busy?'pointer':'not-allowed')+';accent-color:#2684ff;" title="'+(loaded?'Select '+escapeHtml(r.source_key):'No data available')+'"></td>'+ 
'<td style="padding:0 24px;font-size:16px;font-weight:700;color:#1f2937;white-space:nowrap;"><span style="display:inline-flex;vertical-align:middle;margin-right:10px;color:#667085;">'+icon('server',20)+'</span>'+escapeHtml(r.source_key)+'</td>'+ 
'<td style="padding:0 24px;"><span style="display:inline-flex;align-items:center;gap:8px;padding:8px 13px;border-radius:999px;background:'+(loaded?'#e1f6df':'#f3f4f6')+';color:'+(loaded?'#17741c':'#667085')+';font-size:14px;font-weight:700;white-space:nowrap;">'+icon(loaded?'db':'dboff',18)+' '+(loaded?'Data loaded':'No data')+'</span></td>'+ 
'<td style="padding:0 24px;"><button data-pause="'+escapeHtml(r.source_key)+'" '+(busy?'disabled':'')+' style="display:inline-flex;align-items:center;gap:9px;padding:10px 16px;border:1px solid #d7dce2;border-radius:9px;background:#fff;color:#1f2937;font-size:14px;font-weight:600;cursor:'+(busy?'wait':'pointer')+';">'+icon(busy?'info':(paused?'play':'pause'),18)+(busy?'Processing...':(paused?'Resume importing':'Pause importing'))+'</button></td>'+ 
'<td style="padding:0 24px;">'+(loaded?'<button data-purge="'+escapeHtml(r.source_key)+'" '+(busy?'disabled':'')+' style="display:inline-flex;align-items:center;gap:9px;padding:10px 16px;border:1px solid #d7dce2;border-radius:9px;background:#fff;color:#1f2937;font-size:14px;font-weight:600;cursor:'+(busy?'wait':'pointer')+';">'+icon('trash',18)+'Purge data</button>':'<span style="color:#9aa2af;font-size:14px;">—</span>')+'</td>'+ 
'<td style="padding:0 24px;">'+reviewHtml+'</td></tr>';
});
html+='</tbody></table></div>';
tableEl.innerHTML=html;

var selectPage=tableEl.querySelector('#h3-select-page');
if(selectPage){
selectPage.indeterminate=somePageSelected;
selectPage.disabled=pageSelectable.length===0;
selectPage.onclick=function(){toggleCurrentPageSelection(selectPage.checked)};
}

Array.prototype.forEach.call(tableEl.querySelectorAll('[data-select]'),function(b){
b.onclick=function(){toggleRowSelection(b.dataset.select,b.checked)};
});

var ps=root.querySelector('#h3-purge-selected');
if(ps)ps.onclick=function(){if(selectedCount()>0)purgeSelectedData()};

Array.prototype.forEach.call(tableEl.querySelectorAll('[data-pause]'),function(b){
b.onclick=function(){
var k=b.dataset.pause,row=allRows.find(function(r){return r.source_key===k});
if(row)updatePause(k,row.is_paused===true)
}
});

Array.prototype.forEach.call(tableEl.querySelectorAll('[data-purge]'),function(b){
b.onclick=function(){openPurgeChoiceModal(b.dataset.purge)}
});

var selectedMetric=root.querySelector('#h3-selected-count');
if(selectedMetric)selectedMetric.textContent=String(selected)+' selected';
var loadedMetric=root.querySelector('#h3-loaded-count');
if(loadedMetric)loadedMetric.textContent=loadedCount+' / '+totalCount;
var purgeButton=root.querySelector('#h3-purge-selected');
if(purgeButton){
 purgeButton.innerHTML=icon('trash',18)+(selected>0?'Purge '+selected+' selected':'Purge selected');
 purgeButton.disabled=selected===0;
 purgeButton.style.color=selected>0?'#1f2937':'#9aa2af';
 purgeButton.style.borderColor=selected>0?'#d7dce2':'#e5e7eb';
 purgeButton.style.cursor=selected>0?'pointer':'not-allowed';
}
var currentPageText=root.querySelector('#h3-current-page-selection');
if(currentPageText)currentPageText.textContent=selectedOnCurrentPage()+' selected on this page';
renderPagination();
}
